"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[27171],{27452:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"CrosshairController","desc":"Owns the hand crosshair: a `Crosshair` ScreenGui (`IgnoreGuiInset`, so it sits\\non the exact `ViewportSize / 2` the aim rays use) with a `CrossReticle` and the\\nGrabHook circle image.\\n\\nIt shows while the aim camera is on (`Signals.OnShootingCameraToggled`), no\\nturret is mounted (`Signals.OnTurretMounted`; the TurretGui draws its own) and\\nthe character is alive. The aim owner sets what it shows through\\n`Signals.SetCrosshairSource`:\\n\\n- `Style = \\"Cross\\"`: fixed dot + four fixed hairs whose gap is the cone edge,\\n  `CrosshairMath.gapPx(Cone(), FieldOfView, ViewportSize.Y, MinRadiusScale)`.\\n  Only the hairs move. The live FOV is read every frame, so the sprint FOV\\n  change keeps the gap honest.\\n- `Style = \\"Circle\\"` (GrabHook): the circle image at `CircleScale` of the screen\\n  height times the net-perk multiplier (`Signals.RequestReticleScale`).\\n- No source (throwables, anything else in aim mode): the cross at floor gap.\\n\\nOwners clear their own source on unequip / dismount (`CrosshairMath.applySource`:\\na late clear cannot wipe a newer owner\'s source). Leaving aim mode resets the\\nnet-perk multiplier; character removal also clears the source and aim flag. The size eases on one `RenderStepped` bound only while the\\ncrosshair is visible.","realm":["Client"],"source":{"line":28,"path":"src/StarterPlayer/StarterPlayerScripts/CrosshairController.client.luau"}}')}}]);